import React from 'react';
import '../styles/Hero.css';
import { useTheme } from './ThemeContext';

const Hero = () => {
    const { isDarkTheme } = useTheme();

    return (
        <section className={`hero-section ${isDarkTheme ? 'dark-theme' : 'light-theme'}`} id="home">
            <div className="hero-background"></div>
            <div className="hero-overlay"></div>

            <div className="hero-content fade-in-up">
                <p className="hero-eyebrow">TRUSTED LEGAL PARTNERS IN CHENNAI</p>

                <h1 className="hero-title">
                    Law. Perspective.<br />
                    Practice. <span className="hero-highlight">Progress.</span>
                </h1>

                <p className="hero-subtitle">
                    ChennaiLawyers.net is a full-service law firm based in Chennai, offering 
                    practical legal solutions for individuals, businesses and institutions.
                </p>

                <div className="hero-cta-group">
                    <a href="#practice" className="apple-btn primary-btn">OUR PRACTICE AREAS</a>
                    <a href="#contact" className="apple-btn secondary-btn">GET IN TOUCH</a>
                </div>
            </div>
        </section>
    );
};

export default Hero;
